function draw(){const s=el('overlay');s.replaceChildren();s.setAttribute('viewBox',`0 0 ${p().native_width} ${p().native_height}`);for(const [i,q] of blocks.entries())for(const [j,box] of [q.box,...q.lines.map(l=>l.box)].entries()){if(!box)continue;const r=document.createElementNS('http://www.w3.org/2000/svg','rect');['x','y','width','height'].forEach((k,n)=>r.setAttribute(k,box[n]));r.setAttribute('fill','none');r.setAttribute('stroke',i===+el('block').value?(j?'#c32d51':'#176e53'):'#858585');r.setAttribute('stroke-width',j?3:5);s.append(r);}}
function block(){const q=b();el('line').replaceChildren();if(!q){draw();return;}q.lines.forEach((l,i)=>el('line').add(new Option('Line '+l.line_number,i)));el('unit').value=q.unit||'';el('decision').value=q.decision||'UNREGISTERED';el('reason').value=q.reason||'';draw();}
function list(){el('block').replaceChildren();blocks.forEach((q,i)=>el('block').add(new Option(q.block_id+' · '+q.lines.length+' lines',i)));block();}
function page(){const t=p(),saved=reviews[t.task_id];blocks=structuredClone(saved?saved.blocks:(data.candidates.find(c=>c.task_id===t.task_id)?.blocks||[])).map(q=>({...q,unit:q.unit||null,decision:q.decision||'UNREGISTERED',reason:q.reason||''}));el('scan').src=t.image;el('reviewed').checked=saved?.reviewed===true;const uu=data.units.filter(u=>u.folio===t.folio);el('units').textContent=uu.map(u=>u.unit+' '+u.reading+': '+u.line_count+' lines').join('\n');el('unit').replaceChildren();el('unit').add(new Option('Unmapped',''));[...new Set(uu.map(u=>u.unit))].forEach(u=>el('unit').add(new Option(u,u)));list();status('Changing pages discards unsaved edits. Save page review first.');}
el('page').onchange=page;el('block').onchange=block;el('unit').onchange=()=>{if(b())b().unit=el('unit').value||null;};el('decision').onchange=()=>{if(b())b().decision=el('decision').value;};el('reason').oninput=()=>{if(b())b().reason=el('reason').value;};
el('newBlock').onclick=()=>{blocks.push({block_id:'manual-'+Date.now(),box:null,lines:[],unit:null,decision:'UNREGISTERED',reason:''});list();el('block').value=String(blocks.length-1);block();};el('deleteBlock').onclick=()=>{if(!b())return;blocks.splice(+el('block').value,1);list();};function renumber(){if(b())b().lines.forEach((l,i)=>l.line_number=i+1);block();}el('removeLine').onclick=()=>{if(b()){b().lines.splice(+el('line').value,1);renumber();}};el('sort').onclick=()=>{if(b()){b().lines.sort((a,c)=>a.box[1]-c.box[1]||a.box[0]-c.box[0]);renumber();}};
const frame=el('frame'),scan=el('scan');function xy(e){const r=scan.getBoundingClientRect();return[Math.max(0,Math.min(r.width,e.clientX-r.left)),Math.max(0,Math.min(r.height,e.clientY-r.top))];}frame.onpointerdown=e=>{if(!b()||!scan.complete)return;start=xy(e);drag=null;frame.setPointerCapture(e.pointerId);e.preventDefault();};frame.onpointermove=e=>{if(!start)return;const z=xy(e),r=scan.getBoundingClientRect();drag=[Math.min(z[0],start[0])/r.width*p().native_width,Math.min(z[1],start[1])/r.height*p().native_height,Math.abs(z[0]-start[0])/r.width*p().native_width,Math.abs(z[1]-start[1])/r.height*p().native_height].map(Math.round);};frame.onpointerup=()=>{start=null;if(!drag||!b()||drag[2]<1||drag[3]<1)return;if(el('mode').value==='block')b().box=drag;else b().lines.push({line_number:b().lines.length+1,box:drag});block();};
el('save').onclick=()=>{if(blocks.some(q=>!q.reason?.trim())){status('Every block needs a visual decision reason.');return;}reviews[p().task_id]={task_id:p().task_id,reviewed:el('reviewed').checked,blocks:structuredClone(blocks),notes:'Source-only visual registration'};status(Object.keys(reviews).length+' pages saved in this session. Export before closing.');};
el('export').onclick=()=>{if(!el('who').value.trim()||!el('blind').checked||!el('pictures').checked||!el('fresh').checked){status('Registrar ID and truthful independence declarations required.');return;}const d={registrar_id:el('who').value.trim(),fresh_context:true,outcome_blind:true,picture_boxes_unseen:true,pages:Object.values(reviews)};const url=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='REVIEW.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};el('import').onchange=async()=>{try{const d=JSON.parse(await el('import').files[0].text());if(!Array.isArray(d.pages)||d.pages.some(q=>!pages.some(t=>t.task_id===q.task_id)))throw Error('Unknown pages');reviews=Object.fromEntries(d.pages.map(q=>[q.task_id,q]));el('who').value=d.registrar_id||'';el('blind').checked=d.outcome_blind===true;el('pictures').checked=d.picture_boxes_unseen===true;el('fresh').checked=d.fresh_context===true;page();}catch(e){status('Import failed: '+e.message);}};page();
